css:
.background {
  width: 80px;
  height: 80px;
  background-color: #000;
  position: absolute;
  z-index: -1;
  border-radius: 10px;
  box-shadow: 10px 5px 30px;
}

.load-container {
  width: 70px;
  height: 70px;
  display: grid;
  grid-template-columns: repeat(5, 10px);
  grid-template-rows: repeat(5, 10px);
  gap: 5px;
}

.ball {
  width: 10px;
  height: 10px;
  background: red;
  border-radius: 10px;
  animation: size 1s infinite ease-in-out;
}

.ball:nth-child(1) {
  animation-delay: 0s;
}
.ball:nth-child(2) {
  animation-delay: -0.1s;
}
.ball:nth-child(3) {
  animation-delay: -0.2s;
}
.ball:nth-child(4) {
  animation-delay: -0.3s;
}
.ball:nth-child(5) {
  animation-delay: -0.4s;
}
.ball:nth-child(6) {
  animation-delay: -0.5s;
}
.ball:nth-child(7) {
  animation-delay: -0.6s;
}
.ball:nth-child(8) {
  animation-delay: -0.7s;
}
.ball:nth-child(9) {
  animation-delay: -0.8s;
}
.ball:nth-child(10) {
  animation-delay: -0.9s;
}
.ball:nth-child(11) {
  animation-delay: -1s;
}
.ball:nth-child(12) {
  animation-delay: -1.1s;
}
.ball:nth-child(13) {
  animation-delay: -1.2s;
}
.ball:nth-child(14) {
  animation-delay: -1.3s;
}
.ball:nth-child(15) {
  animation-delay: -1.4s;
}
.ball:nth-child(16) {
  animation-delay: -1.5s;
}
.ball:nth-child(17) {
  animation-delay: -1.6s;
}
.ball:nth-child(18) {
  animation-delay: -1.7s;
}
.ball:nth-child(19) {
  animation-delay: -1.8s;
}
.ball:nth-child(20) {
  animation-delay: -1.9s;
}
.ball:nth-child(21) {
  animation-delay: -2s;
}
.ball:nth-child(22) {
  animation-delay: -2.1s;
}
.ball:nth-child(23) {
  animation-delay: -2.2s;
}
.ball:nth-child(24) {
  animation-delay: -2.3s;
}
.ball:nth-child(25) {
  animation-delay: -2.5s;
}

.ball:nth-child(even) {
  background: blue;
}

@keyframes size {
  0% {
    transform: scale(0.2);
  }
  50% {
    transform: scale(1);
  }
  100% {
    transform: scale(0.2);
  }
}
